@js:(function(){
  var UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) Chrome/134.0.0.0 Safari/537.36';
  var s = '';
  try { s = String((typeof java !== 'undefined' && java.baseUrl) || (typeof baseUrl !== 'undefined' ? baseUrl : '') || ''); } catch(e0) { s = ''; }
  var m = s.match(/trackId=([^&]+)/);
  if (!m || !m[1]) { m = s.match(/\/song\/(\d+)/); }
  if (!m || !m[1]) { return ''; }
  var tid = m[1];
  try {
    var seo = 'https://beta-luna.douyin.com/luna/h5/seo_track?track_id=' + tid + '&device_platform=web';
    var o1 = { headers: { 'User-Agent': UA, 'Referer': 'https://www.douyin.com/' } };
    var r1 = java.ajax(seo + ',' + JSON.stringify(o1));
    if (!r1) { return ''; }
    var tp = JSON.parse(r1).track_player || {};
    var pu = tp.url_player_info || '';
    if (!pu) { return ''; }
    var o2 = { headers: { 'User-Agent': UA, 'Referer': 'https://www.douyin.com/' } };
    var r2 = java.ajax(pu + ',' + JSON.stringify(o2));
    if (!r2) { return ''; }
    var pl = ((JSON.parse(r2).Result || {}).Data || {}).PlayInfoList || [];
    var best = '';
    var bv = -1;
    for (var i = 0; i < pl.length; i++) {
      var u = pl[i].MainPlayUrl || pl[i].BackupPlayUrl1 || pl[i].BackupPlayUrl2 || '';
      if (!u) { continue; }
      var q = String(pl[i].Quality || pl[i].QualityDesc || '').toLowerCase();
      var v = 0;
      if (q.indexOf('highest') >= 0 || q === 'hi' || q === 'exhigh') { v = 4; }
      else if (q.indexOf('higher') >= 0 || q === 'sq' || q === 'lossless') { v = 3; }
      else if (q.indexOf('normal') >= 0 || q === 'hq') { v = 2; }
      else if (q === 'lq' || q.indexOf('low') >= 0) { v = 1; }
      if (v > bv) { bv = v; best = u; }
    }
    if (!best && pl.length) { best = pl[0].MainPlayUrl || pl[0].BackupPlayUrl1 || ''; }
    return best || '';
  } catch (e2) { return ''; }
})();

