@js:(function(){
  var raw = '';
  try { raw = String(result || ''); } catch(e0) { raw = ''; }
  var j = null;
  try { j = JSON.parse(raw); } catch(e1) { j = null; }
  var out = [];
  if (j) {
    var items = j.items || [];
    for (var i = 0; i < items.length; i++) {
      var ent = items[i].entity || items[i] || {};
      var tw = ent.track_wrapper || {};
      var tr = tw.track || ent.track || ent.audio || null;
      if (!tr || !tr.id) { continue; }
      var al = tr.album || {};
      var uc = al.url_cover || al.cover || {};
      var ul = uc.urls || uc.url_list || [];
      var cov = '';
      if (ul && ul.length) { cov = String(ul[0]) + String(uc.uri || ''); }
      var ar = tr.artists || [];
      var an = [];
      for (var a = 0; a < ar.length; a++) { an.push(String(ar[a].name || '')); }
      out.push({
        name: String(tr.name || ''),
        author: an.join('/'),
        coverUrl: cov,
        bookUrl: 'https://www.qishui.com/song/' + String(tr.id) + '?trackId=' + String(tr.id),
        lastChapter: '时长' + Math.round((tr.duration || 0) / 1000) + '秒'
      });
    }
  }
  if (out.length) { return out; }
  var head = '⚠️ 未能解析出歌曲';
  var body = raw ? raw.substring(0, 300) : '（空响应：请求失败/被拦截）';
  if (!raw) {
    head = '❌ 无返回（请求失败或被拦截）';
  } else if (raw.indexOf('Request denied') >= 0 || raw.indexOf('403') >= 0) {
    head = '❌ 被拦截（403/网关拒绝）';
  } else if (raw.indexOf('<html') >= 0) {
    head = '❌ 返回HTML页面（可能需登录）';
  } else if (!j) {
    head = '⚠️ 非JSON返回';
  } else {
    var code = (j.status_code !== undefined) ? j.status_code : ((j.code !== undefined) ? j.code : '');
    var msg = j.message || j.msg || j.errmsg || '';
    if (msg || (code !== '' && String(code) !== '0')) {
      head = '⚠️ 接口错误: ' + String(msg) + ' (code=' + String(code) + ')';
    } else {
      head = '⚠️ 接口通但无歌曲（region/风控？）';
    }
  }
  return [{ name: head, author: body, coverUrl: '', bookUrl: '', lastChapter: '' }];
})();

